// nextSteps.js — the EDUCATIONAL "what next" layer, now TIERED: immediate/bedside actions, first-line
// investigations, confirmatory/specialist tests, and monitoring/safety-netting, plus urgency + referral.
// These are TEACHING PROMPTS, not clinical directives — no drug doses, no definitive management. The app
// pairs them with an explicit "not clinical advice" disclaimer.
//
//   nextStepsFor(site) -> { immediate, investigations, confirmatory, monitoring, urgency, referral, curated }
//
// Curated per-site entries (by site.id, else level_part) carry the site-specific first-line investigations
// and referral; the immediate / confirmatory / monitoring tiers are DERIVED from urgency + region so EVERY
// site gets a full, structured plan (derive-don't-store spirit). A curated entry may override any tier via
// its optional `extra` ({ immediate, confirmatory, monitoring }).
import { expectedFindings } from "../engine/forward.js";
import { CAUSES } from "./causes.js";
import { pathologyPlanFor } from "./pathologyNextSteps.js";

const ns = (investigations, urgency, referral, extra = {}) => ({ investigations, urgency, referral, ...extra });

// ---- derived ophthalmic imaging prompt (2026-08-11, CHIASM FIX 2026-08-18) ----
// Fundal photography and OCT of the retinal nerve fibre layer must surface wherever the picture involves
// ANTERIOR VISUAL PATHWAY damage or PAPILLOEDEMA. Both triggers are DERIVED rather than hand-listed per
// site, so a future site or cause gets the prompt automatically:
//   * anterior pathway — the site's own expectedFindings contain an anterior visual finding, OR the site
//     itself sits at or anterior to the lateral geniculate
//   * papilloedema — the site's curated causes raise papilloedema, raised ICP, hydrocephalus or sinus thrombosis
// Perimetry is deliberately NOT repeated here: the curated entries already prompt it, and this layer is
// adding the imaging that was missing from the whole workup layer, not restating what is there.
//
// THE CHIASM MATTERS, and the original list ignored it. These are ANTERIOR-pathway tests — they measure
// the disc and the retinal ganglion cell axons. A RETRO-CHIASMAL field defect from a post-geniculate
// lesion leaves those axons, and the discs, entirely normal: retrograde trans-synaptic degeneration is a
// research finding, not a work-up step. Before this fix, 22 sites fired on a retro-chiasmal token alone
// and 16 of them were post-geniculate — which is how entering LEG WEAKNESS came to surface fundal
// photography, MCA and anterior choroidal both being candidates for weak_leg that merely PREDICT a field
// defect the patient was never reported to have.
//
// `homonymous_hemianopia` is therefore NOT a trigger token: it is produced both by the optic tract (where
// OCT is right) and by the occipital cortex (where it is not), so the token cannot distinguish them and
// the SITE has to. Hence the second, site-based rule below.
const VISUAL_FINDING = /^(bitemporal_hemianopia|optic_neuropathy|altitudinal_defect|central_scotoma|optic_atrophy|retinal_pallor|va_reduced_no_pinhole)@/;

// Sites AT or ANTERIOR to the lateral geniculate, where the retinal ganglion cell axon is itself in the
// lesion, so disc pallor and RNFL thinning are real and gradeable — band atrophy after an optic tract
// lesion being the classic example. The LGN is included because the retinal ganglion cell axons TERMINATE
// there, so a geniculate lesion still degenerates them.
//
// The anterior choroidal artery is deliberately NOT here even though it supplies the tract and part of the
// LGN: its lesion presents as a stroke and takes a stroke work-up, and prompting OCT there would teach the
// wrong first move.
const PREGENICULATE_PARTS = new Set(["optic_tract", "lgn"]);
const isPregeniculate = site => site.level === "visual_pathway" && PREGENICULATE_PARTS.has(site.part);

// Causes implying DISC SWELLING. Normal-pressure hydrocephalus is excluded BY NAME and deliberately: the
// pressure is normal, so there is no papilloedema, and prompting for it there would teach the wrong thing.
const RAISES_PRESSURE = /papilloedema|raised intracranial pressure|raised pressure|intracranial hypertension|hydrocephalus|sagittal sinus thrombosis|venous sinus thrombosis|Foster.Kennedy/i;
const NOT_RAISED = /normal.pressure hydrocephalus/i;

function hasFieldDefect(site) {
  if (isPregeniculate(site)) return true;
  let exp; try { exp = [...expectedFindings(site)]; } catch { return false; }
  return exp.some(t => VISUAL_FINDING.test(t));
}
function raisesPapilloedema(site) {
  const key = CAUSES[site.id] ? site.id : `${site.level}_${site.part}`;
  return (CAUSES[key] || []).some(c =>
    !NOT_RAISED.test(c.name) && RAISES_PRESSURE.test(`${c.name} ${c.feature || ""} ${c.pathognomonic || ""}`));
}

export function ophthalmicImaging(site) {
  const field = hasFieldDefect(site), pressure = raisesPapilloedema(site);
  if (!field && !pressure) return [];
  const why = field && pressure
    ? "it gives an objective baseline for the field defect AND quantifies any disc swelling, which serial written descriptions never do reliably"
    : field
      ? "OCT shows whether it has already THINNED, which tells you how long the lesion has been there and how much vision is recoverable; a normal-looking disc with established thinning changes the prognosis, and the photographs give an objective baseline to compare against later"
      : "serial photographs and OCT quantify papilloedema objectively and track it far better than repeated written descriptions, and OCT separates true swelling from disc drusen or a congenitally crowded disc";
  return [`FUNDAL PHOTOGRAPHY and OCT of the retinal nerve fibre layer — ${why}`];
}

// Radiculopathy workups are genuinely near-identical apart from the level: the same imaging, the same
// conservative-first management, the same red flags. Building them from a shared spine keeps the safety
// netting CONSISTENT across all 17 roots (rather than depending on 17 copy-paste blocks staying in sync),
// while `bedside` and `extra*` carry what actually differs level to level.
const rootNS = ({ spine, bedside, urgency = "routine", referral, invExtra = [], confExtra = [], monExtra = [] }) => ns(
  [`MRI ${spine} spine — the investigation of choice for a radiculopathy that is severe, progressive or not settling`,
   ...invExtra,
   "Plain films add little; do NOT let a normal X-ray reassure you when the history suggests malignancy or infection"],
  urgency,
  referral,
  { immediate: [
      ...bedside,
      "RED FLAGS that change the pathway: unrelenting NIGHT pain, weight loss, fever, known malignancy, or a progressive neurological deficit — any of these means image urgently rather than treating conservatively",
    ],
    confirmatory: [
      "Nerve conduction studies and EMG if the level is uncertain, or to separate a root lesion from a peripheral nerve or plexus lesion",
      ...confExtra,
      "Bloods (FBC, CRP/ESR) and imaging for infection or malignancy where the red flags above are present",
    ],
    monitoring: [
      ...monExtra,
      "Most radiculopathies improve with analgesia, activity modification and physiotherapy over 6-12 weeks — review rather than rushing to surgery",
      "Refer for surgical opinion if there is progressive weakness, intolerable pain despite adequate treatment, or failure to settle",
    ] });

